do $batch$
declare v_course text:='meteorology-forecasting-foundations'; v_ch uuid; v_unit uuid;
begin
 if not exists(select 1 from public.academy_courses where id=v_course) then raise exception 'course missing'; end if;
 if exists(select 1 from public.academy_lessons where slug like 'applied2-%') then raise exception 'batch already inserted'; end if;
 insert into public.academy_chapters(course_id,title,description,sort_order,published) values(v_course,'النمذجة والاستشعار والتحقق والذكاء الاصطناعي للأرصاد','دفعة من مئة درس متقدم في النمذجة العددية والأقمار الصناعية والرادار والديناميكا والمسبار والتحقق والآنكاستنغ والتجميع وإدارة التنبؤ والذكاء الاصطناعي.',69,false) returning id into v_ch;
 insert into public.academy_units(chapter_id,title,description,sort_order,published) values(v_ch,'النمذجة العددية','عشرة دروس تطبيقية متقدمة في النمذجة العددية',1,false) returning id into v_unit;
 insert into public.academy_lessons(course_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title,chapter_id,unit_id)
 select v_course,x.slug,x.title,x.summary,x.content,false,x.sort_order,'advanced',x.estimated_minutes,x.learning_objectives,'النمذجة والاستشعار والتحقق والذكاء الاصطناعي للأرصاد','النمذجة العددية',v_ch,v_unit
 from jsonb_to_recordset($payload$[{"slug":"applied2-1-1","title":"معادلات الحركة","summary":"درس متقدم في معادلات الحركة ضمن النمذجة العددية، يتضمن مفاهيم وبيانات وخطوات تطبيقية ومثالاً وتقويماً ذاتياً.","content":{"version":1,"blocks":[{"type":"heading","text":"نواتج التعلم"},{"type":"list","items":["شرح المبادئ العلمية في معادلات الحركة","تحليل بيانات ومنتجات معادلات الحركة","التحقق من النتائج وتحديد عدم اليقين في معادلات الحركة"]},{"type":"heading","text":"الأساس العلمي"},{"type":"text","text":"يعالج هذا الدرس معادلات الحركة ضمن وحدة النمذجة العددية. يبدأ الفهم بتحديد المتغيرات الفيزيائية وعلاقاتها، ثم معرفة كيف تنتج القياسات أو المنتجات التحليلية، وما الدقة المكانية والزمنية التي تمثلها. يجب الفصل بين الرصد المباشر والتقدير والاستنتاج ومخرجات النماذج."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["بيانات موثقة المصدر والتوقيت والموقع والوحدات","خرائط أو قياسات متزامنة مع الظاهرة المدروسة","بيانات مرجعية مستقلة للتحقق","سجل ضبط الجودة والبيانات المفقودة"]},{"type":"heading","text":"خطوات التنفيذ"},{"type":"list","items":["حدد سؤال التحليل والفترة والحيز المكاني","تحقق من الوحدات والتوقيت والاكتمال","استخرج المتغيرات والأنماط ذات الصلة","قارن النتيجة بقياس مستقل أو خط أساس","وثق الافتراضات والانحياز والقيود"]},{"type":"heading","text":"حالة تطبيقية"},{"type":"example","title":"تطبيق تدريبي: معادلات الحركة","text":"افترض توفر بيانات جوية مرتبطة بـمعادلات الحركة عبر عدة أوقات ومواقع. تظهر البيانات اختلافاً بين القياسات أو المنتجات، والمطلوب تحليل النمط والتحقق من جودة المدخلات. الحالة افتراضية ولا تمثل رصداً حقيقياً.","solution":"وحد التوقيت والوحدات أولاً، ثم افحص القيم الناقصة والشاذة ومصدر كل متغير. طبق المبدأ العلمي الخاص بـمعادلات الحركة، وقارن النتائج بمصدر مرجعي مستقل إن توفر. اشرح أسباب الاختلاف الممكنة، وافصل الاستنتاج المدعوم عن الافتراض، ثم اذكر القيود وعدم اليقين."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"أنشئ تقريراً قصيراً عن معادلات الحركة يتضمن المدخلات ومصادرها، خطوات التحليل، جدولاً أو مخططاً للنتائج، واستنتاجاً يوضح حدود الاستخدام."},{"type":"heading","text":"ضبط الجودة"},{"type":"list","items":["عدم دمج أوقات غير متطابقة دون توضيح","عدم استنتاج قيمة غير مقاسة من لون الخريطة وحده","عدم إخفاء الانحياز أو البيانات المفقودة","عدم تعميم علاقة تجريبية خارج مجال معايرتها"]},{"type":"callout","text":"محتوى تدريبي فقط. لا تستخدم النتائج الافتراضية في قرار تشغيلي دون تحقق مستقل والرجوع إلى المعايير والجهات المختصة."},{"type":"heading","text":"اختبار ذاتي"},{"type":"question","question":"ما الخطوة الأساسية قبل تفسير نتائج معادلات الحركة؟","options":["فحص المصدر والتوقيت والوحدات وجودة البيانات","اعتماد أول قيمة دون مراجعة","تجاهل البيانات المفقودة","اعتبار المثال الافتراضي رصداً حقيقياً"],"answer":0,"explanation":"التحقق من المصدر والتوقيت والوحدات والجودة أساس التحليل الموثوق."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يتطلب إتقان معادلات الحركة فهماً فيزيائياً وتحليلاً منهجياً وتحققاً مستقلاً وتواصلاً يوضح حدود الاستنتاج."}]},"learning_objectives":["شرح المبادئ العلمية في معادلات الحركة","تحليل بيانات ومنتجات معادلات الحركة","التحقق من النتائج وتحديد عدم اليقين في معادلات الحركة"],"sort_order":13000,"estimated_minutes":45},{"slug":"applied2-1-2","title":"الشبكات الأفقية والرأسية","summary":"درس متقدم في الشبكات الأفقية والرأسية ضمن النمذجة العددية، يتضمن مفاهيم وبيانات وخطوات تطبيقية ومثالاً وتقويماً ذاتياً.","content":{"version":1,"blocks":[{"type":"heading","text":"نواتج التعلم"},{"type":"list","items":["شرح المبادئ العلمية في الشبكات الأفقية والرأسية","تحليل بيانات ومنتجات الشبكات الأفقية والرأسية","التحقق من النتائج وتحديد عدم اليقين في الشبكات الأفقية والرأسية"]},{"type":"heading","text":"الأساس العلمي"},{"type":"text","text":"يعالج هذا الدرس الشبكات الأفقية والرأسية ضمن وحدة النمذجة العددية. يبدأ الفهم بتحديد المتغيرات الفيزيائية وعلاقاتها، ثم معرفة كيف تنتج القياسات أو المنتجات التحليلية، وما الدقة المكانية والزمنية التي تمثلها. يجب الفصل بين الرصد المباشر والتقدير والاستنتاج ومخرجات النماذج."},{"type":"heading","text":"البيانات المطلوبة"}