 from jsonb_to_recordset($payload$[{"slug":"applied2-2-1","title":"المدارات الثابتة والقطبية","summary":"درس متقدم في المدارات الثابتة والقطبية ضمن الأقمار الصناعية، يتضمن مفاهيم وبيانات وخطوات تطبيقية ومثالاً وتقويماً ذاتياً.","content":{"version":1,"blocks":[{"type":"heading","text":"نواتج التعلم"},{"type":"list","items":["شرح المبادئ العلمية في المدارات الثابتة والقطبية","تحليل بيانات ومنتجات المدارات الثابتة والقطبية","التحقق من النتائج وتحديد عدم اليقين في المدارات الثابتة والقطبية"]},{"type":"heading","text":"الأساس العلمي"},{"type":"text","text":"يعالج هذا الدرس المدارات الثابتة والقطبية ضمن وحدة الأقمار الصناعية. يبدأ الفهم بتحديد المتغيرات الفيزيائية وعلاقاتها، ثم معرفة كيف تنتج القياسات أو المنتجات التحليلية، وما الدقة المكانية والزمنية التي تمثلها. يجب الفصل بين الرصد المباشر والتقدير والاستنتاج ومخرجات النماذج."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["بيانات موثقة المصدر والتوقيت والموقع والوحدات","خرائط أو قياسات متزامنة مع الظاهرة المدروسة","بيانات مرجعية مستقلة للتحقق","سجل ضبط الجودة والبيانات المفقودة"]},{"type":"heading","text":"خطوات التنفيذ"},{"type":"list","items":["حدد سؤال التحليل والفترة والحيز المكاني","تحقق من الوحدات والتوقيت والاكتمال","استخرج المتغيرات والأنماط ذات الصلة","قارن النتيجة بقياس مستقل أو خط أساس","وثق الافتراضات والانحياز والقيود"]},{"type":"heading","text":"حالة تطبيقية"},{"type":"example","title":"تطبيق تدريبي: المدارات الثابتة والقطبية","text":"افترض توفر بيانات جوية مرتبطة بـالمدارات الثابتة والقطبية عبر عدة أوقات ومواقع. تظهر البيانات اختلافاً بين القياسات أو المنتجات، والمطلوب تحليل النمط والتحقق من جودة المدخلات. الحالة افتراضية ولا تمثل رصداً حقيقياً.","solution":"وحد التوقيت والوحدات أولاً، ثم افحص القيم الناقصة والشاذة ومصدر كل متغير. طبق المبدأ العلمي الخاص بـالمدارات الثابتة والقطبية، وقارن النتائج بمصدر مرجعي مستقل إن توفر. اشرح أسباب الاختلاف الممكنة، وافصل الاستنتاج المدعوم عن الافتراض، ثم اذكر القيود وعدم اليقين."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text